from pathlib import Path
p=Path('public/products');p.mkdir(parents=True,exist_ok=True)
start='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 500 500"><defs><linearGradient id="dark" x2="1" y2="1"><stop stop-color="#454c45"/><stop offset=".5" stop-color="#161c18"/><stop offset="1" stop-color="#333b31"/></linearGradient><linearGradient id="edge"><stop stop-color="#697062"/><stop offset=".4" stop-color="#242c22"/><stop offset="1" stop-color="#0b100c"/></linearGradient><linearGradient id="glass" x2="1" y2="1"><stop stop-color="#f9e9c8" stop-opacity=".8"/><stop offset=".5" stop-color="#bb924d" stop-opacity=".55"/><stop offset="1" stop-color="#e7d1a1" stop-opacity=".9"/></linearGradient><linearGradient id="screen" x2="1" y2="1"><stop stop-color="#d9f7a1"/><stop offset="1" stop-color="#7a9b57"/></linearGradient><filter id="shadow"><feGaussianBlur stdDeviation="9"/></filter></defs>'
def save(name,body): (p/(name+'.svg')).write_text(start+body+'</svg>')
save('headset','''<ellipse cx="255" cy="420" rx="135" ry="15" fill="#35412a" opacity=".13" filter="url(#shadow)"/><path d="M113 282V207C113 25 391 22 391 211V290" fill="none" stroke="#101610" stroke-width="39"/><path d="M114 220C105 44 397 30 389 222" fill="none" stroke="url(#edge)" stroke-width="22"/><path d="M130 163C165 68 334 70 372 165" fill="none" stroke="#616859" stroke-width="3"/><path d="M112 222L104 305M391 222L398 305" stroke="#7c8573" stroke-width="12"/><g transform="rotate(-12 132 310)"><rect x="83" y="226" width="93" height="170" rx="43" fill="#0f1511"/><rect x="92" y="235" width="69" height="151" rx="32" fill="url(#dark)"/><rect x="137" y="238" width="40" height="145" rx="20" fill="#121811"/><path d="M105 255V354" stroke="#4b5444" stroke-width="2"/></g><g transform="rotate(12 368 310)"><rect x="323" y="226" width="95" height="170" rx="43" fill="#0d130e"/><rect x="337" y="235" width="72" height="151" rx="32" fill="url(#dark)"/><rect x="323" y="238" width="34" height="145" rx="17" fill="#182017"/><path d="M393 257V356" stroke="#59634c" stroke-width="2"/><path d="M365 290l21 26m-22 0l23-26" stroke="#b6d585" stroke-width="3"/></g><path d="M102 339Q47 381 111 408L191 415" fill="none" stroke="#222b20" stroke-width="10"/><rect x="182" y="406" width="35" height="15" rx="7" fill="#171f15"/>''')
keys=''.join(f'<rect x="{70+c*29}" y="{183+r*33}" width="24" height="25" rx="4" fill="#{"454c42" if r<3 else "30392b"}" stroke="#6c7c58" stroke-width=".6"/><text x="{82+c*29}" y="{199+r*33}" text-anchor="middle" font-family="monospace" font-size="6" fill="#cbe5b1">{"QWERTYUIOPAS"[(c+r)%11]}</text>' for r in range(4) for c in range(12))
save('keyboard','<g transform="rotate(-12 250 250)"><rect x="48" y="166" width="404" height="167" rx="15" fill="#111a13"/><rect x="48" y="158" width="404" height="166" rx="15" fill="url(#dark)" stroke="#788269" stroke-width="2"/>'+keys+'<rect x="158" y="282" width="143" height="22" rx="4" fill="#45533b"/><path d="M70 320h356" stroke="#cbf487" stroke-width="2" opacity=".7"/></g>')
save('mouse','''<g transform="rotate(26 250 250)"><path d="M250 94C163 94 148 173 143 264C135 361 175 407 250 407S365 361 357 264C352 173 337 94 250 94Z" fill="url(#dark)" stroke="#70795f" stroke-width="2"/><path d="M250 96V245M153 242Q250 279 347 242" fill="none" stroke="#0c120c" stroke-width="4"/><rect x="238" y="144" width="24" height="55" rx="11" fill="#0c120c" stroke="#737d65" stroke-width="2"/><path d="M245 153h10m-10 8h10m-10 8h10m-10 8h10m-10 8h10" stroke="#809267"/><path d="M214 320l33 35 38-35-8 46h-50Z" fill="#c8ee8e" opacity=".8"/><path d="M161 283C160 370 197 390 247 392" fill="none" stroke="#515d44" stroke-width="2"/></g>''')
save('controller','''<g transform="rotate(-14 250 250)"><path d="M130 157C83 164 63 254 66 330C68 390 103 394 152 333L195 290H305L350 336C399 394 435 386 433 327C431 253 415 169 371 158C308 143 196 143 130 157Z" fill="url(#dark)" stroke="#5f6e52" stroke-width="3"/><circle cx="172" cy="246" r="38" fill="#151d13" stroke="#657655" stroke-width="4"/><circle cx="172" cy="246" r="27" fill="#333f2a"/><circle cx="298" cy="288" r="32" fill="#131c12" stroke="#637651" stroke-width="3"/><path d="M229 252v44m-22-22h44" stroke="#11180f" stroke-width="16"/><g fill="#c8e99e"><circle cx="350" cy="207" r="13"/><circle cx="378" cy="235" r="13"/><circle cx="350" cy="263" r="13"/><circle cx="322" cy="235" r="13"/></g><path d="M226 182h52" stroke="#889478" stroke-width="5" stroke-linecap="round"/><circle cx="251" cy="210" r="6" fill="#c6e78e"/></g>''')
for name,label,color in [('perfume','SAUVAGE','#171e22'),('amber','AMBER NOIR','#4e3423'),('decant','BLEU','#183140')]:
 if name=='decant':body=f'<rect x="208" y="140" width="84" height="270" rx="12" fill="url(#glass)" stroke="#b7a98d"/><rect x="206" y="95" width="88" height="75" rx="8" fill="url(#dark)"/><rect x="216" y="242" width="68" height="110" fill="#f4f0e5"/><text x="250" y="278" text-anchor="middle" font-size="12" font-family="serif">{label}</text><text x="250" y="300" text-anchor="middle" font-size="7">NEXO / DECANT</text><text x="250" y="330" text-anchor="middle" font-size="9">10 ML</text>'
 else:body=f'<rect x="158" y="166" width="184" height="240" rx="18" fill="{color}" stroke="#6c7161" stroke-width="2"/><rect x="175" y="180" width="150" height="207" rx="12" fill="url(#glass)" opacity=".23"/><path d="M175 195V365" stroke="#fff" opacity=".25" stroke-width="4"/><rect x="195" y="91" width="110" height="85" rx="8" fill="url(#dark)"/><path d="M199 106h102m-102 13h102m-102 13h102m-102 13h102" stroke="#616957" opacity=".4"/><text x="250" y="264" fill="#f1e8cd" text-anchor="middle" font-size="22" font-family="serif" letter-spacing="2">{label}</text><text x="250" y="290" text-anchor="middle" fill="#dacfae" font-size="8" letter-spacing="3">EAU DE PARFUM</text><text x="250" y="364" text-anchor="middle" fill="#dacfae" font-size="13" font-family="serif">{ "Dior" if name=="perfume" else "NEXO"}</text>'
 save(name,body)
for name,title,sub in [('digital','BUILD YOUR','NEXT IDEA.'),('planner','LESS CHAOS.','MORE FOCUS.'),('ebook','PLAY. LEARN.','REPEAT.')]:
 save(name,f'<g transform="rotate(-10 250 250)"><rect x="108" y="101" width="278" height="316" rx="5" fill="#19251d"/><rect x="104" y="91" width="278" height="316" rx="5" fill="#d4e9b4" stroke="#a3bb87"/><path d="M120 94v310" stroke="#a2b987"/><text x="143" y="134" fill="#556b42" font-family="monospace" font-size="9">NEXO / DIGITAL RESOURCES</text><text x="143" y="207" fill="#24351d" font-family="sans-serif" font-size="31" font-weight="bold">{title}</text><text x="143" y="246" fill="#24351d" font-family="sans-serif" font-size="31" font-weight="bold">{sub}</text><path d="M145 286h180m-180 8h180m-180 8h150" stroke="#a0b889"/><circle cx="317" cy="350" r="24" fill="#263c21"/><path d="M307 360l20-20m-19 0h19v19" fill="none" stroke="#d2efad" stroke-width="2"/><text x="143" y="370" font-family="monospace" font-size="8" fill="#556b42">CREATE SOMETHING GREAT ↗</text></g>')
